function solve(customer, plan, daysSincePurchase) {
    // Refund policy logic:
    // - Annual plans: refund only if purchased within 30 days
    // - Monthly plans: refund only if purchased within 14 days
    // - Other customers: stricter policy (within 7 days for annual, 3 days for monthly)

    const isAnnual = plan === 'annual';
    const isAcme = customer === 'Acme';

    let maxDays;
    if (isAnnual) {
        maxDays = isAcme ? 7 : 30;
    } else {
        maxDays = isAcme ? 3 : 14;
    }

    return daysSincePurchase <= maxDays;
}
